From 2e4aabf5a17089a0e84be13486a4a60b59b609f9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 14:01:17 +0100
Subject: [PATCH] plasmaquick: don't create the QML of an applet that failed to
 launch

When an applet was already marked as failed, its QML still got created
and completed behind the error message, and an empty list of QML errors
replaced the reason in the details. Skip its QML and keep the reason.

BUG: 528864
---
 src/plasmaquick/appletquickitem.cpp | 29 ++++++++++++++++++-----------
 1 file changed, 18 insertions(+), 11 deletions(-)

diff --git a/src/plasmaquick/appletquickitem.cpp b/src/plasmaquick/appletquickitem.cpp
index ab3fa7ebb..270afc31f 100644
--- a/src/plasmaquick/appletquickitem.cpp
+++ b/src/plasmaquick/appletquickitem.cpp
@@ -540,17 +540,22 @@ AppletQuickItem *AppletQuickItem::itemForApplet(Plasma::Applet *applet)
     appletContext->setContextObject(i18nContext);
     QQmlEngine::setContextForObject(i18nContext, appletContext);

-    AppletQuickItem *item = qobject_cast<AppletQuickItem *>(component.beginCreate(appletContext));
+    AppletQuickItem *item = nullptr;

-    if (pc && pc->isContainment()) {
-        item = qobject_cast<ContainmentItem *>(item);
-        if (!item && !component.isError()) {
-            applet->setLaunchErrorMessage(i18n("The root item of %1 must be of type ContainmentItem", applet->mainScript().toString()));
-        }
-    } else {
-        item = qobject_cast<PlasmoidItem *>(item);
-        if (!item && !component.isError()) {
-            applet->setLaunchErrorMessage(i18n("The root item of %1 must be of type PlasmoidItem", applet->mainScript().toString()));
+    // Don't run any code of an applet that has already failed, e.g. one the shell disabled
+    if (!applet->failedToLaunch()) {
+        item = qobject_cast<AppletQuickItem *>(component.beginCreate(appletContext));
+
+        if (pc && pc->isContainment()) {
+            item = qobject_cast<ContainmentItem *>(item);
+            if (!item && !component.isError()) {
+                applet->setLaunchErrorMessage(i18n("The root item of %1 must be of type ContainmentItem", applet->mainScript().toString()));
+            }
+        } else {
+            item = qobject_cast<PlasmoidItem *>(item);
+            if (!item && !component.isError()) {
+                applet->setLaunchErrorMessage(i18n("The root item of %1 must be of type PlasmoidItem", applet->mainScript().toString()));
+            }
         }
     }

@@ -608,7 +613,9 @@ AppletQuickItem *AppletQuickItem::itemForApplet(Plasma::Applet *applet)
                     reason += error.toString() + QLatin1Char('\n');
                     errorList << error.toString();
                 }
-                errorData[QStringLiteral("errors")] = QJsonArray::fromStringList(errorList);
+                if (!errorList.isEmpty()) {
+                    errorData[QStringLiteral("errors")] = QJsonArray::fromStringList(errorList);
+                }
             }
             errorData[QStringLiteral("appletName")] = applet->pluginMetaData().name();
             reason += i18n("Error loading QML file: %1 %2", component.url().toString(), reason);
-- 
2.53.0

From e3586f18b24957c98c524cd45dd69e75d1f502ef Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 14:01:17 +0100
Subject: [PATCH] shell: disable a widget for one session after it crashes
 Plasma

A user-installed widget that crashed Plasma usually crashed it again on
every restart, and nothing said which widget it was. The crash handler
now logs it, and the next start shows it as disabled instead of loading.

BUG: 528864
---
 shell/main.cpp        |  1 +
 shell/shellcorona.cpp | 50 +++++++++++++++++++++++++++++++++++++++++++
 shell/shellcorona.h   |  6 ++++++
 3 files changed, 57 insertions(+)

diff --git a/shell/main.cpp b/shell/main.cpp
index ce385db4e4..28eedbd0a4 100644
--- a/shell/main.cpp
+++ b/shell/main.cpp
@@ -189,6 +189,7 @@ int main(int argc, char *argv[])
         if (!cliOptions.isSet(noRespawnOption)) {
             KCrash::setFlags(KCrash::AutoRestart);
         }
+        KCrash::setEmergencySaveFunction(ShellCorona::recordCrashedWidget);

         // Tells libnotificationmanager that we're the only true application that may own notification and job progress services
         qApp->setProperty("_plasma_dbus_master", true);
diff --git a/shell/shellcorona.cpp b/shell/shellcorona.cpp
index 51bde18ac6..45e42983df 100644
--- a/shell/shellcorona.cpp
+++ b/shell/shellcorona.cpp
@@ -28,6 +28,8 @@
 #include <QQmlContext>
 #include <QQuickItemGrabResult>
 #include <QScreen>
+#include <QStandardPaths>
+#include <QThread>
 #include <QUrl>
 #include <QVariant>

@@ -87,6 +89,10 @@ using namespace std::chrono_literals;
 using namespace Qt::StringLiterals;

 static const int s_configSyncDelay = 10000; // 10 seconds
+static QQmlEngine *s_engine = nullptr;
+
+// Exported by QtQml for debuggers: the current JavaScript stack of an engine, innermost frame first
+extern "C" char *qt_v4StackTraceForEngine(void *executionEngine);

 Q_DECLARE_METATYPE(QColor)

@@ -131,6 +137,16 @@ ShellCorona::ShellCorona(QObject *parent)

 void ShellCorona::init()
 {
+    m_engine = PlasmaQuick::globalEngine();
+    s_engine = m_engine.get();
+
+    KConfigGroup stateGroup(KSharedConfig::openStateConfig(), u"General"_s);
+    m_crashedWidget = stateGroup.readEntry("CrashedWidget", QString());
+    if (!m_crashedWidget.isEmpty()) {
+        stateGroup.deleteEntry("CrashedWidget");
+        stateGroup.sync();
+    }
+
 #if USE_SCRIPTING
     connect(this, &Plasma::Corona::containmentCreated, this, [this](Plasma::Containment *c) {
         executeSetupPlasmoidScript(c, c);
@@ -154,6 +170,16 @@ void ShellCorona::init()
         if (cont->containmentType() == Plasma::Containment::Panel || cont->containmentType() == Plasma::Containment::CustomPanel) {
             connect(cont, &QObject::destroyed, this, &ShellCorona::panelContainmentDestroyed);
         }
+        if (!m_crashedWidget.isEmpty()) {
+            const auto applets = cont->applets();
+            for (Plasma::Applet *applet : applets) {
+                if (applet->pluginMetaData().pluginId() == m_crashedWidget) {
+                    applet->setLaunchErrorMessage(
+                        i18n("%1 was disabled because it caused Plasma to crash. It will be loaded again the next time Plasma starts.",
+                             applet->pluginMetaData().name()));
+                }
+            }
+        }
     });

     m_desktopDefaultsConfig = KConfigGroup(KSharedConfig::openConfig(kPackage().filePath("defaults")), u"Desktop"_s);
@@ -309,6 +335,7 @@ void ShellCorona::init()
 ShellCorona::~ShellCorona()
 {
     m_closingDown = true;
+    s_engine = nullptr;
     destroyDesktopsAndPanels();

     while (!containments().isEmpty()) {
@@ -2997,6 +3024,29 @@ void ShellCorona::activateLauncherMenu(const QString &screenName)
     }
 }

+void ShellCorona::recordCrashedWidget(int signal)
+{
+    Q_UNUSED(signal)
+    // Only the main thread runs widget code; another thread's crash can't be attributed to the code it happens to be running
+    if (!s_engine || !QThread::isMainThread()) {
+        return;
+    }
+
+    const QString stackTrace = QString::fromLocal8Bit(qt_v4StackTraceForEngine(s_engine->handle()));
+    const QString userPlasmoidsPath = u"file=\""_s + QStandardPaths::writableLocation(QStandardPaths::GenericDataLocation) + u"/plasma/plasmoids/"_s;
+    const qsizetype pathIndex = stackTrace.indexOf(userPlasmoidsPath);
+    if (pathIndex < 0) {
+        return;
+    }
+    const qsizetype idIndex = pathIndex + userPlasmoidsPath.size();
+    const QString pluginId = stackTrace.mid(idIndex, stackTrace.indexOf(u'/', idIndex) - idIndex);
+
+    fprintf(stderr, "plasmashell: crashed while running code of the widget %s\n", qPrintable(pluginId));
+    KConfigGroup stateGroup(KSharedConfig::openStateConfig(), u"General"_s);
+    stateGroup.writeEntry("CrashedWidget", pluginId);
+    stateGroup.sync();
+}
+
 QString ShellCorona::defaultShell()
 {
     KSharedConfig::Ptr startupConf = KSharedConfig::openConfig(QStringLiteral("plasmashellrc"));
diff --git a/shell/shellcorona.h b/shell/shellcorona.h
index a85cd9aa07..ae39ebcdc2 100644
--- a/shell/shellcorona.h
+++ b/shell/shellcorona.h
@@ -15,6 +15,7 @@
 #include <QDBusContext>
 #include <QDBusVariant>
 #include <QPointer>
+#include <QQmlEngine>
 #include <QSet>
 #include <QTimer>

@@ -110,6 +111,9 @@ public:

     static QString defaultShell();

+    // KCrash emergency save function: remembers which user-installed widget was running when Plasma crashed
+    static void recordCrashedWidget(int signal);
+
     // Set all Desktop containments (for all activities) associated to a given screen to this new screen.
     // swapping ones that had newScreen to oldScreen if existing. Panels are ignored
     void swapDesktopScreens(uint oldScreen, uint newScreen);
@@ -297,6 +301,8 @@ private:
 #endif

     KSharedConfig::Ptr m_config;
+    std::shared_ptr<QQmlEngine> m_engine;
+    QString m_crashedWidget;

     // Accent color setting
     KConfigWatcher::Ptr m_kdeGlobalsConfigWatcher;
-- 
2.53.0
